#!/usr/bin/env python3
"""Inference on new paired-noise trajectories using a locally trained checkpoint."""
import argparse
from pathlib import Path
import sys
ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT))
import numpy as np
import torch
from chaos.basis import haar_values
from chaos.models import SDENO, FSPDENO
from scripts.reproduce import sde_features, phi_features


def predict(checkpoint, data, device="cpu"):
    # Load only checkpoints generated by this project; torch 2.4 uses pickle.
    saved = torch.load(checkpoint, map_location="cpu", weights_only=False)
    cfg = saved["config"]
    if "kind" in saved:
        model = SDENO(saved["feature_dim"],saved["state_dim"],cfg["width"],saved["kind"]=="heston")
        features = sde_features(data["dw"],saved["basis"],cfg["dt"],cfg[saved["kind"]+"_order"])
        t = np.linspace(0,cfg["steps"]*cfg["dt"],cfg["steps"]+1)
        model.load_state_dict(saved["state_dict"])
        model.to(device).eval()
        with torch.no_grad():
            pred = model(torch.tensor(features,device=device),torch.tensor(t,dtype=torch.float32,device=device)).cpu().numpy()
        return pred*saved["scale"]
    model = FSPDENO(saved["in_channels"],haar_values(cfg["steps"],cfg["temporal_basis_count"]),
                    cfg["width"],cfg["fourier_modes"],cfg["layers"])
    features = phi_features(data,cfg,saved["scale"])
    model.load_state_dict(saved["state_dict"])
    model.to(device).eval()
    chunks = []
    with torch.no_grad():
        for i in range(0,len(features),cfg["batch_size"]):
            chunks.append(model(torch.tensor(features[i:i+cfg["batch_size"]],device=device)).cpu().numpy())
    return np.concatenate([data["u0"][:,None],np.concatenate(chunks)*saved["scale"]],axis=1)


if __name__ == "__main__":
    parser=argparse.ArgumentParser()
    parser.add_argument("checkpoint",type=Path)
    parser.add_argument("input",type=Path,help="NPZ with dw; SPDE additionally u0 and qstd")
    parser.add_argument("output",type=Path)
    parser.add_argument("--device",default="cpu")
    args=parser.parse_args()
    result=predict(args.checkpoint,dict(np.load(args.input)),args.device)
    np.savez_compressed(args.output,prediction=result)
    print(args.output,result.shape)
